class _PigeonCodec extends StandardMessageCodec {
  const _PigeonCodec();
  @override
  void writeValue(WriteBuffer buffer, Object? value) {
    if (value is int) {
      buffer.putUint8(4);
      buffer.putInt64(value);
    }    else if (value is GhostLockRequest) {
      buffer.putUint8(129);
      writeValue(buffer, value.encode());
    }    else if (value is GhostLockPreflight) {
      buffer.putUint8(130);
      writeValue(buffer, value.encode());
    }    else if (value is GhostLockStartResult) {
      buffer.putUint8(131);
      writeValue(buffer, value.encode());
    }    else if (value is GhostLockChunk) {
      buffer.putUint8(132);
      writeValue(buffer, value.encode());
    }    else if (value is GhostLockUserProfile) {
      buffer.putUint8(133);
      writeValue(buffer, value.encode());
    }    else if (value is GhostLockImportResult) {
      buffer.putUint8(134);
      writeValue(buffer, value.encode());
    }    else if (value is GhostLockProbeResult) {
      buffer.putUint8(135);
      writeValue(buffer, value.encode());
    }    else if (value is GhostLockFieldNode) {
      buffer.putUint8(136);
      writeValue(buffer, value.encode());
    }    else if (value is GhostLockExecutionField) {
      buffer.putUint8(137);
      writeValue(buffer, value.encode());
    }    else if (value is GhostLockProfileConfig) {
      buffer.putUint8(138);
      writeValue(buffer, value.encode());
    } else {
      super.writeValue(buffer, value);
    }
  }

  @override
  Object? readValueOfType(int type, ReadBuffer buffer) {
    switch (type) {
      case 129:
        return GhostLockRequest.decode(readValue(buffer)!);
      case 130:
        return GhostLockPreflight.decode(readValue(buffer)!);
      case 131:
        return GhostLockStartResult.decode(readValue(buffer)!);
      case 132:
        return GhostLockChunk.decode(readValue(buffer)!);
      case 133:
        return GhostLockUserProfile.decode(readValue(buffer)!);
      case 134:
        return GhostLockImportResult.decode(readValue(buffer)!);
      case 135:
        return GhostLockProbeResult.decode(readValue(buffer)!);
      case 136:
        return GhostLockFieldNode.decode(readValue(buffer)!);
      case 137:
        return GhostLockExecutionField.decode(readValue(buffer)!);
      case 138:
        return GhostLockProfileConfig.decode(readValue(buffer)!);
      default:
        return super.readValueOfType(type, buffer);
    }
  }
}

